-- Initial website content, generated once from the Phase 2 typed content files
-- (src/content/services.ts and faqs.ts, removed in the same commit).
-- Editable afterwards from /admin/content. Safe to re-run: existing slugs are left untouched.

insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('website-design-development', 1, true, 'Website Design and Development', 'Design & Development', 'A custom business website, planned around how your customers decide and built to load fast.', 'Website Design & Development for Businesses', 'Custom website design and development for service businesses: clear structure, conversion-focused pages, fast load times and a site you can update yourself.', 'Website design & development', 'A website built to *win* the enquiry, not just look good', 'I plan, design and build business websites around one job: helping the right visitor understand what you do, trust you, and get in touch. Clean code, fast pages and an editor you can actually use.', '[{"title":"Visitors leave without acting","body":"The site looks fine but doesn''t guide anyone towards a call, booking or enquiry."},{"title":"It doesn''t explain what you do","body":"Services are buried, vague or written for you rather than for the customer."},{"title":"Built on a theme you''ve outgrown","body":"Every change is a fight with a template that was never designed for your business."},{"title":"You can''t update it yourself","body":"Small edits need a developer, so the site goes stale."}]'::jsonb, '["Sitemap and page structure based on how your customers decide","Custom visual design for desktop and mobile","Responsive build on WordPress or a modern framework, chosen for your needs","Enquiry forms connected to your inbox or CRM","On-page SEO foundations: titles, headings, structured data, sitemap","Performance and accessibility checks before launch","A walkthrough so you can edit content confidently"]'::jsonb, '[{"title":"Discover","body":"We agree goals, audience and the actions the site must drive."},{"title":"Structure","body":"Sitemap and wireframes come first, so content and layout serve the goal."},{"title":"Design & build","body":"Visual design, then a clean, responsive build you review on a staging link."},{"title":"Launch & handover","body":"Final QA, launch, analytics set-up and a recorded handover."}]'::jsonb, '["Service businesses launching or relaunching online","Consultants and professionals who need credibility fast","Companies replacing a DIY or template site"]'::jsonb, '[{"question":"Which platform will my website be built on?","answer":"It depends on how you''ll run it. WordPress suits teams that want a familiar editor and a large plugin ecosystem; a modern framework suits sites that need maximum speed or custom functionality. I''ll recommend one and explain why before we start."},{"question":"Will I be able to edit the website myself?","answer":"Yes. Content you''ll change regularly is set up as editable fields or blocks, and you get a walkthrough at handover."},{"question":"Do you write the website content?","answer":"I structure every page and write the headings, calls to action and microcopy. For longer copy, I can work from your notes, edit what you supply, or recommend a specialist copywriter."},{"question":"Who owns the website when it''s finished?","answer":"You do. Domains, hosting accounts and the site itself are set up in your name, and you receive all logins."}]'::jsonb, '["website-redesign","wordpress-elementor-development","technical-seo"]'::jsonb, 'blueprint', '{"title":"Planning a new website?","body":"Tell me about your business and what the site needs to do. I''ll reply with next steps and an outline of scope.","label":"Start a website project"}'::jsonb) on conflict (slug) do nothing;
insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('website-redesign', 2, true, 'Website Redesign and Modernisation', 'Redesign', 'Modernise an outdated site without losing the search visibility and content you''ve built.', 'Website Redesign & Modernisation Services', 'Redesign an outdated business website without losing rankings: content audit, modern design, faster performance and careful URL redirects at launch.', 'Website redesign', 'Modernise your website *without* starting from zero', 'A redesign should keep what already works — your search visibility, your best content, your customers'' habits — and fix what doesn''t. I audit first, then redesign with a careful migration plan.', '[{"title":"It looks dated next to competitors","body":"First impressions are costing you credibility before anyone reads a word."},{"title":"It''s slow and hard to use on mobile","body":"Layouts break, images are heavy and key actions are hard to reach."},{"title":"You''re worried about losing rankings","body":"Redesigns that change URLs carelessly can undo years of search visibility."},{"title":"Content has grown messy","body":"Duplicate pages, outdated offers and a navigation nobody can follow."}]'::jsonb, '["Audit of current content, structure, speed and search visibility","Keep / improve / remove plan for every existing page","Modern responsive design using your existing brand or a refreshed one","URL mapping and 301 redirects to protect search visibility","Performance, accessibility and SEO checks before and after launch","Post-launch monitoring of crawl errors and broken links"]'::jsonb, '[{"title":"Audit","body":"Measure what the current site does well and where it falls short."},{"title":"Plan","body":"Decide what to keep, merge or retire, and map every URL."},{"title":"Redesign","body":"Design and build on staging while the current site stays live."},{"title":"Migrate","body":"Launch with redirects, then monitor search and analytics closely."}]'::jsonb, '["Established businesses with an ageing website","Sites that rank but don''t convert","Teams moving away from an unmaintainable theme or builder"]'::jsonb, '[{"question":"Will a redesign hurt my Google rankings?","answer":"Any large change carries some risk, which is why the plan includes URL mapping, redirects and preserving content that performs. No one can guarantee rankings, but a careful migration avoids the most common causes of lost visibility."},{"question":"Can you keep my current branding?","answer":"Yes. I can modernise the site within your existing brand or suggest a light refresh."},{"question":"Does my current site stay online during the redesign?","answer":"Yes. The new site is built on a private staging link and only replaces the live site at launch."},{"question":"Can you redesign a site you didn''t build?","answer":"Yes — most redesigns start from someone else''s site. The audit tells us what can be reused and what should be rebuilt."}]'::jsonb, '["website-design-development","website-performance-optimisation","technical-seo"]'::jsonb, 'before-after', '{"title":"Ready to modernise your site?","body":"Share your current website address and what''s frustrating you about it. I''ll start with a quick review.","label":"Request a redesign review"}'::jsonb) on conflict (slug) do nothing;
insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('wordpress-elementor-development', 3, true, 'WordPress and Elementor Development', 'WordPress & Elementor', 'Clean, maintainable WordPress and Elementor builds your team can edit without breaking.', 'WordPress & Elementor Developer for Hire', 'WordPress and Elementor development done properly: global styles, reusable templates, lean plugins and editing that stays consistent as your site grows.', 'WordPress & Elementor', 'WordPress that stays *tidy* as your site grows', 'Elementor and WordPress are powerful — and easy to turn into a slow, inconsistent site. I build with global styles, reusable templates and a lean plugin set, so editing stays simple and pages stay fast.', '[{"title":"Every page is styled differently","body":"Fonts, spacing and buttons drift because nothing uses global settings."},{"title":"Too many plugins","body":"Overlapping add-ons slow the site and multiply security updates."},{"title":"Edits break the layout","body":"Changing one section unexpectedly affects another, especially on mobile."},{"title":"Custom features don''t exist","body":"You need functionality no off-the-shelf widget provides."}]'::jsonb, '["Elementor or block-editor builds using global colours, fonts and spacing","Reusable templates for headers, footers, archives and key sections","Custom post types and fields for structured content","Lean plugin selection with a documented purpose for each","Custom widgets or functionality where off-the-shelf options fall short","Responsive QA across phones, tablets and desktops"]'::jsonb, '[{"title":"Review","body":"Understand the content you manage and who edits it."},{"title":"System","body":"Set up global styles and templates before building pages."},{"title":"Build","body":"Assemble pages from the system, adding custom code only where needed."},{"title":"Handover","body":"Document the templates and show your team how to edit safely."}]'::jsonb, '["Businesses already invested in WordPress","Teams who want to edit pages visually","Agencies needing a reliable Elementor developer"]'::jsonb, '[{"question":"Do you work with Elementor Pro?","answer":"Yes. I use Elementor Pro''s theme builder, global settings and dynamic content where they fit, and avoid unnecessary third-party add-ons."},{"question":"Can you fix or extend an existing Elementor site?","answer":"Yes. I can tidy up inconsistent styling, convert repeated sections into templates, and add new pages or features."},{"question":"Is Elementor bad for performance?","answer":"It can be when overused. With global styles, fewer nested containers, optimised assets and caching, Elementor sites can perform well."},{"question":"Do you build custom WordPress plugins?","answer":"Where a requirement isn''t met by a well-maintained plugin, I write focused custom code instead of stacking add-ons."}]'::jsonb, '["website-design-development","website-bug-fixes","woocommerce-development"]'::jsonb, 'editable-blocks', '{"title":"Need a WordPress or Elementor developer?","body":"Tell me about the site and the work involved — a new build, a template system or a custom feature.","label":"Discuss your WordPress project"}'::jsonb) on conflict (slug) do nothing;
insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('website-bug-fixes', 4, true, 'Website Bug Fixes and Technical Troubleshooting', 'Bug Fixes', 'Diagnose and fix broken layouts, errors, failed updates and forms that stopped sending.', 'Website Bug Fixes & Technical Troubleshooting', 'Fast, careful fixes for broken websites: critical errors, layout bugs, failed updates, forms that stopped sending and plugin conflicts, tested before going live.', 'Bug fixes & troubleshooting', 'Something''s broken. Let''s find *why*, then fix it properly', 'A broken form or a white screen costs you enquiries every hour it stays live. I diagnose the root cause, fix it safely — on a backup or staging copy where possible — and tell you what happened in plain language.', '[{"title":"Critical error or blank page","body":"The site, or part of it, is down after an update or change."},{"title":"Forms stopped arriving","body":"Enquiries are being lost to spam filters, mail settings or a broken plugin."},{"title":"Layout broke on mobile","body":"Sections overlap, menus don''t open or buttons can''t be tapped."},{"title":"Update conflicts","body":"A theme, plugin or PHP update left the site in an unstable state."}]'::jsonb, '["Backup before any change","Root-cause diagnosis, not a surface patch","Fix applied and tested on staging where possible","Plain-language summary of the cause and the fix","Recommendations to prevent the issue recurring"]'::jsonb, '[{"title":"Reproduce","body":"Confirm the issue and collect logs, errors and recent changes."},{"title":"Isolate","body":"Narrow it down to the plugin, code, server or setting involved."},{"title":"Fix","body":"Apply the smallest safe fix and test it in context."},{"title":"Verify","body":"Check related pages and forms, then report back."}]'::jsonb, '["Sites that broke after an update","Business owners whose previous developer is unavailable","Agencies needing overflow technical support"]'::jsonb, '[{"question":"How quickly can you look at my issue?","answer":"Tell me how urgent it is in the enquiry form. Availability varies, and I''ll confirm a realistic response time before starting."},{"question":"What access will you need?","answer":"Usually an administrator login and hosting or file access. I''ll ask only for what the fix requires, and you can revoke access when we''re done."},{"question":"Do you charge if you can''t fix it?","answer":"Diagnosis takes time, so it''s normally billable. I''ll agree the scope and cost with you before work starts."},{"question":"Do you only fix WordPress sites?","answer":"WordPress is the most common, but I also troubleshoot sites built with other platforms and custom code. Mention the platform in your enquiry."}]'::jsonb, '["website-security-maintenance","wordpress-elementor-development","website-performance-optimisation"]'::jsonb, 'bug-trace', '{"title":"Got a website problem right now?","body":"Describe what''s broken and when it started. Include your website address so I can take a first look.","label":"Report a website issue"}'::jsonb) on conflict (slug) do nothing;
insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('technical-seo', 5, true, 'Technical and On-Page SEO', 'Technical SEO', 'Make sure search engines can crawl, understand and index the pages that matter.', 'Technical & On-Page SEO Services', 'Technical and on-page SEO for business websites: crawlability, indexing, site structure, structured data and page-level optimisation, explained clearly.', 'Technical & on-page SEO', 'Help search engines *understand* what you offer', 'Good content can''t rank if search engines can''t crawl, index or understand it. I fix the technical foundations and the on-page signals, then explain what changed and why. No ranking guarantees — just a site that''s built to be found.', '[{"title":"Important pages aren''t indexed","body":"Search Console reports exclusions, duplicates or crawl errors you can''t decode."},{"title":"Pages compete with each other","body":"Several pages target the same search, so none of them performs."},{"title":"Titles and headings are inconsistent","body":"Search results show truncated, duplicated or generic titles."},{"title":"No structured data","body":"Search engines get little context about your business and services."}]'::jsonb, '["Technical audit: crawlability, indexing, canonicals, redirects, sitemap, robots","Search Console and analytics set-up or review","Site structure and internal linking recommendations","Page titles, meta descriptions and heading hierarchy","Structured data for your business, services and FAQs","Prioritised action list, with fixes implemented where agreed"]'::jsonb, '[{"title":"Crawl","body":"Crawl the site the way a search engine does and review Search Console."},{"title":"Diagnose","body":"Identify indexing, duplication and structure issues."},{"title":"Fix","body":"Implement technical and on-page fixes in priority order."},{"title":"Monitor","body":"Track indexing and search performance after changes."}]'::jsonb, '["Sites with indexing problems in Search Console","Businesses before or after a redesign","Owners who want a technical baseline before investing in content"]'::jsonb, '[{"question":"Can you guarantee first-page rankings?","answer":"No — and you should be cautious of anyone who does. Rankings depend on competition, content and factors outside anyone''s control. I make sure your site is technically sound and clearly structured, which is the foundation for sustainable organic growth."},{"question":"Is this the same as content marketing or link building?","answer":"No. This service covers technical and on-page SEO. I can advise on content structure and topics, but I don''t sell link-building packages."},{"question":"How long until I see results?","answer":"Technical fixes are often picked up within weeks as pages are recrawled, but search performance depends on many factors. I''ll explain what to monitor and when."},{"question":"Do I need Google Search Console?","answer":"Yes — it''s free and the best source of data on how Google sees your site. I can set it up and verify ownership for you."}]'::jsonb, '["website-performance-optimisation","website-redesign","website-design-development"]'::jsonb, 'crawl-index', '{"title":"Want a technical SEO baseline?","body":"Send your website address and any Search Console issues you''ve noticed. I''ll outline what an audit would cover.","label":"Request an SEO review"}'::jsonb) on conflict (slug) do nothing;
insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('website-security-maintenance', 6, true, 'Website Security and Maintenance', 'Security & Maintenance', 'Updates, backups, monitoring and hardening, so your website stays online and trustworthy.', 'Website Security & Maintenance Plans', 'Ongoing website maintenance and security: tested updates, off-site backups, uptime monitoring, hardening and malware clean-up for business websites.', 'Security & maintenance', 'Keep your website *secure*, updated and backed up', 'Most hacked or broken websites have the same story: skipped updates, no tested backups, nobody watching. A maintenance routine prevents most of it — and means there''s a plan when something does go wrong.', '[{"title":"Updates are piling up","body":"You''re afraid to update because the last update broke something."},{"title":"Backups are untested","body":"You have backups — probably — but have never tried restoring one."},{"title":"The site was hacked","body":"Spam pages, redirects or warnings in the browser or Search Console."},{"title":"No one notices downtime","body":"The site goes down and you hear about it from a customer."}]'::jsonb, '["Scheduled core, theme and plugin updates, tested before going live","Off-site backups with periodic restore tests","Uptime and security monitoring","Hardening: user roles, login protection, file permissions, security headers","Malware clean-up and recovery when needed","A short monthly report of what was done"]'::jsonb, '[{"title":"Assess","body":"Review the current state, access, backups and risks."},{"title":"Harden","body":"Close obvious gaps and set up backups and monitoring."},{"title":"Maintain","body":"Run updates and checks on a regular schedule."},{"title":"Report","body":"Summarise work done and flag anything that needs a decision."}]'::jsonb, '["Business sites that need to stay online","WordPress and WooCommerce sites with many plugins","Owners recovering from a hack"]'::jsonb, '[{"question":"Can you clean up a hacked website?","answer":"Yes. I''ll identify how the site was compromised, remove malicious code, restore clean files, close the entry point and help you request a review if Google has flagged the site."},{"question":"Is maintenance a monthly plan?","answer":"Usually, yes — the right frequency depends on how complex the site is. I''ll recommend a schedule after an initial assessment."},{"question":"Where are backups stored?","answer":"Off-site, separately from your hosting, so a server problem doesn''t take your backups with it."},{"question":"Does this include hosting?","answer":"No. Hosting stays in your name with your provider. I can recommend suitable hosts and help you migrate."}]'::jsonb, '["website-bug-fixes","website-performance-optimisation","woocommerce-development"]'::jsonb, 'security-layers', '{"title":"Want someone looking after your website?","body":"Tell me about your site and how it''s currently maintained. I''ll suggest a sensible routine.","label":"Ask about maintenance"}'::jsonb) on conflict (slug) do nothing;
insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('website-performance-optimisation', 7, true, 'Website Performance and Core Web Vitals Optimisation', 'Performance', 'Faster pages and better Core Web Vitals through targeted, measured fixes.', 'Website Speed & Core Web Vitals Optimisation', 'Make your website faster: Core Web Vitals diagnosis, image and script optimisation, caching and hosting advice, with before-and-after measurements.', 'Performance & Core Web Vitals', 'A faster website, *measured* before and after', 'Slow pages frustrate visitors and weaken search performance. I measure what''s actually slowing your site, fix the biggest causes first, and show you the before-and-after numbers.', '[{"title":"Failing Core Web Vitals","body":"Search Console flags poor LCP, INP or CLS on your key pages."},{"title":"Heavy pages on mobile","body":"Large images, sliders and scripts make phones wait."},{"title":"Layout jumps while loading","body":"Content shifts as fonts, ads or images load, causing mis-taps."},{"title":"Slow server response","body":"Every page starts late because of hosting or uncached pages."}]'::jsonb, '["Baseline measurements using lab and field data","Image, font, CSS and JavaScript optimisation","Caching and CDN configuration","Reduction of unnecessary plugins and third-party scripts","Layout-shift fixes for stable loading","Before-and-after report with remaining recommendations"]'::jsonb, '[{"title":"Measure","body":"Record lab and real-user data for your key pages."},{"title":"Prioritise","body":"Rank fixes by impact on the metrics that matter."},{"title":"Optimise","body":"Implement changes and test that nothing breaks."},{"title":"Report","body":"Re-measure and explain what improved and what''s left."}]'::jsonb, '["Sites failing Core Web Vitals in Search Console","Image-heavy and page-builder sites","WooCommerce stores with slow product and checkout pages"]'::jsonb, '[{"question":"What are Core Web Vitals?","answer":"They''re Google''s metrics for loading (Largest Contentful Paint), responsiveness (Interaction to Next Paint) and visual stability (Cumulative Layout Shift), measured from real visitors."},{"question":"Can you guarantee a 100 PageSpeed score?","answer":"No. Lab scores vary between runs and are only one signal. I focus on real-user metrics and meaningful improvements for your visitors."},{"question":"Will optimisation change how my site looks?","answer":"Usually not. Most improvements happen behind the scenes. If a visual element is a major cause — like a heavy slider — I''ll discuss alternatives first."},{"question":"Do I need new hosting?","answer":"Sometimes. If server response time is a bottleneck I''ll show you the data and recommend options; often, caching and optimisation are enough."}]'::jsonb, '["technical-seo","website-redesign","woocommerce-development"]'::jsonb, 'vitals', '{"title":"Is your website slower than it should be?","body":"Share your website address and the pages that matter most. I''ll start with a performance baseline.","label":"Request a speed review"}'::jsonb) on conflict (slug) do nothing;
insert into public.services (slug, position, published, name, short_name, summary, meta_title, meta_description, eyebrow, headline, intro, problems, deliverables, approach, ideal_for, faqs, related, demo, cta) values ('woocommerce-development', 8, true, 'WooCommerce Design and Customisation', 'WooCommerce', 'Online stores with clear product pages, a smooth checkout and the custom features you need.', 'WooCommerce Design & Customisation', 'WooCommerce store design and customisation: clearer product pages, smoother checkout, custom functionality, payment and shipping set-up, and faster store pages.', 'WooCommerce', 'An online store that''s *easier* to buy from', 'Every extra step between product and payment loses customers. I design and customise WooCommerce stores so products are easy to understand, checkout is straightforward, and you can manage orders without workarounds.', '[{"title":"Shoppers abandon checkout","body":"Too many fields, surprise costs or confusing steps."},{"title":"Product pages don''t sell","body":"Thin information, poor images and unclear options."},{"title":"Store pages are slow","body":"Large catalogues, filters and plugins weigh every page down."},{"title":"You need custom behaviour","body":"Pricing rules, product options or integrations that plugins don''t cover cleanly."}]'::jsonb, '["Store design: shop, category, product, cart and checkout templates","Checkout simplification and trust signals","Payment gateway and shipping configuration with your providers","Custom product options, pricing rules or integrations","Store performance optimisation","Order-management walkthrough for your team"]'::jsonb, '[{"title":"Review","body":"Walk through the store as a customer and as an administrator."},{"title":"Design","body":"Improve templates, starting with product and checkout."},{"title":"Customise","body":"Build the functionality your products and processes need."},{"title":"Test","body":"Place test orders across payment and shipping scenarios."}]'::jsonb, '["Small and medium online shops","Businesses moving from marketplaces to their own store","Stores with custom product or pricing requirements"]'::jsonb, '[{"question":"Which payment gateways can you set up?","answer":"Any gateway with a supported WooCommerce integration that your business is eligible for, depending on your country and provider account."},{"question":"Can you improve an existing store?","answer":"Yes. Most WooCommerce projects are improvements to existing stores rather than new builds."},{"question":"Can you migrate products from another platform?","answer":"Usually, yes. Migration depends on the source platform and how products are structured; I''ll assess it before quoting."},{"question":"Do you handle product photography or listings?","answer":"No, but I''ll set up templates so your product content is presented well and easy to add."}]'::jsonb, '["wordpress-elementor-development","website-performance-optimisation","website-security-maintenance"]'::jsonb, 'checkout-flow', '{"title":"Let''s improve your online store","body":"Tell me about your store, the platform it''s on and what''s not working. I''ll suggest where to start.","label":"Discuss your store"}'::jsonb) on conflict (slug) do nothing;

insert into public.faqs (scope, question, answer, position)
select 'general', q, a, p from (values
  ('Do you work with clients outside Bangladesh?', 'Yes. I work remotely with businesses in the United Kingdom, United States, Europe and Bangladesh, and schedule calls to suit your time zone.', 1),
  ('Which currencies can I pay in?', 'Invoices can be issued in USD, GBP, EUR or BDT. Available payment methods are listed on each invoice.', 2),
  ('How much does a website cost?', 'It depends on scope: the number of pages, functionality, content and integrations. After a short consultation you''ll receive a fixed quote with a clear list of what''s included.', 3),
  ('Do you take a deposit?', 'Larger projects normally start with a deposit, with the balance tied to milestones or launch. Smaller fixes may be invoiced on completion. Terms are agreed before work starts.', 4),
  ('Can I follow my project''s progress?', 'Yes. Clients get a private project area showing status, milestones, updates, invoices and payments.', 5)
) as v(q, a, p)
where not exists (select 1 from public.faqs where scope = 'general');
